{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "A-VI, a triterpenoid saponin with multiple sugar residues, reached 248.7 ng/g in rat brain after systemic dosing, directly demonstrating that large polar glycosides can achieve measurable CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "A glucose-bearing small molecule crossed the BBB in rats via GLUT1-mediated transport, showing that sugar-containing molecules can access the brain through active mechanisms despite high polarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Anemoside B4, a multi-sugar triterpenoid saponin, was detected in rat brain after oral administration, supporting brain penetration of oligosaccharide-like natural products.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple related glycosides and saponins demonstrate measurable brain penetration in rodents despite high polarity and large size, and their transfer scores are moderate; this direct experimental evidence outweighs the physicochemical prior and supports meaningful CNS access for the query oligosaccharide, though uncertainty remains due to lack of direct cyclodextrin data.",
  "evidence_gaps": [
    "No direct brain, plasma, CSF, or uptake measurement exists for the exact query cyclodextrin derivative.",
    "The positive analogues are mostly saponins or flavonoid glycosides with lipophilic aglycones, whereas the query is a cyclic oligosaccharide lacking such an aglycone.",
    "The mechanism of brain entry for the query is unknown; cyclodextrins may not be recognized by glucose transporters such as GLUT1.",
    "Reported brain concentrations in the analogues are often low (ng/g range) and may not always equate to meaningful pharmacological exposure."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "moderate",
      "card_ids": ["C05"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "saponin BBB penetration"
    },
