      "applicability": "moderate",
      "card_ids": ["C10"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "glucose-transporter-mediated BBB penetration"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C04"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "saponin BBB penetration"
    }
  ],
  "revision_action": "initial"
}

